#include "reports.h"
#include "budget.h"
#include "date_utils.h"
#include "storage.h"
#include "ui.h"
#include "validation.h"
#include <stdio.h>
#include <string.h>

static int inMonth(const Transaction *t,int m,int y){Date d;return parseDate(t->expense.date,&d)&&d.month==m&&d.year==y;}
static int reportInputs(int *m,int *y){return readInt("Month (1-12): ",1,12,m)&&readInt("Year: ",1,9999,y);}
static void monthlyReport(const AppState *a,int m,int y,FILE *out){double cats[CATEGORY_COUNT+MAX_CATEGORIES]={0},payments[PAYMENT_COUNT]={0},total=0,high=0;size_t counts[CATEGORY_COUNT+MAX_CATEGORIES]={0},payCounts[PAYMENT_COUNT]={0},n=0;const Transaction *highest=NULL;
    for(size_t i=0;i<a->transactionCount;i++)if(inMonth(&a->transactions[i],m,y)){const Transaction *t=&a->transactions[i];n++;total+=t->expense.amount;size_t ci=categoryIndexForTransaction(a,t);cats[ci]+=t->expense.amount;counts[ci]++;payments[t->paymentType]+=t->expense.amount;payCounts[t->paymentType]++;if(!highest||t->expense.amount>high){highest=t;high=t->expense.amount;}}
    const Budget *b=findBudget(a,m,y);fprintf(out,"Monthly Expense Report — %02d-%04d\nTransactions: %zu\nTotal spending: Rs. %.2f\n",m,y,n,total);
    if(highest)fprintf(out,"Highest expense: ID %d, %s, Rs. %.2f\nAverage expense: Rs. %.2f\n",highest->expense.id,highest->expense.description,high,total/(double)n);else fprintf(out,"Highest expense: N/A\nAverage expense: N/A\n");
    fputs("\nCategory totals:\n",out);for(size_t c=0;c<CATEGORY_COUNT+a->categoryCount;c++)if(counts[c])fprintf(out,"  %-20s %3zu  Rs. %.2f\n",categoryDisplayNameAt(a,c),counts[c],cats[c]);
    fputs("\nPayment totals:\n",out);for(int p=0;p<PAYMENT_COUNT;p++)fprintf(out,"  %-8s %3zu  Rs. %.2f\n",PAYMENT_NAMES[p],payCounts[p],payments[p]);
    if(b){double u=b->budgetAmount?total/b->budgetAmount*100:0;fprintf(out,"\nBudget: Rs. %.2f\nRemaining: Rs. %.2f\nUtilization: %.2f%% (%s)\n",b->budgetAmount,b->budgetAmount-total,u,b->budgetAmount?budgetStatus(u):"Zero budget");}else fputs("\nBudget: not configured\n",out);
}
int exportMonthlyReport(const AppState *a,int month,int year){if(month<1||month>12||year<1||year>9999){printError("Invalid report month or year.");return 0;}if(!ensureDataDirectories())return 0;char path[80];snprintf(path,sizeof path,"reports/monthly_report_%04d_%02d.txt",year,month);FILE *f=fopen(path,"w");if(!f){printError("Cannot create monthly report file.");return 0;}Date now;char date[DATE_SIZE]="unknown";if(currentDate(&now))formatDate(now,date,sizeof date);
    fprintf(f,"STUDENT EXPENSE TRACKER — MONTHLY REPORT\nGenerated: %s\n========================================\n\n",date);monthlyReport(a,month,year,f);fputs("\nTransactions:\n",f);for(size_t i=0;i<a->transactionCount;i++)if(inMonth(&a->transactions[i],month,year)){const Transaction *t=&a->transactions[i];fprintf(f,"ID %d | %s | %-18s | %-32s | Rs. %.2f | %s\n",t->expense.id,t->expense.date,categoryName(t),t->expense.description,t->expense.amount,PAYMENT_NAMES[t->paymentType]);}
    int ok=fclose(f)==0;if(!ok){printError("Failed to finish the monthly report file.");return 0;}printSuccess("Report exported successfully.");printf("  Location: %s\n",path);return 1;}

static void daily(const AppState *a){char date[DATE_SIZE];if(!readRequiredString("Date (DD-MM-YYYY): ",date,sizeof date))return;Date d;if(!parseDate(date,&d)){printError("Invalid date.");return;}size_t n=0;double total=0;printSection("DAILY EXPENSE REPORT");printf("  Date: %s\n",date);printTransactionTableHeader();for(size_t i=0;i<a->transactionCount;i++)if(!strcmp(a->transactions[i].expense.date,date)){printTransactionTableRow(&a->transactions[i]);total+=a->transactions[i].expense.amount;n++;}if(!n)printInfo("No expenses were recorded for this date.");printSeparator();printf("Transactions: %zu | Total: Rs. %.2f\n",n,total);}
static void yearReport(const AppState *a){int y;if(!readInt("Year: ",1,9999,&y))return;double total=0;size_t n=0;double months[12]={0};for(size_t i=0;i<a->transactionCount;i++){Date d;if(parseDate(a->transactions[i].expense.date,&d)&&d.year==y){n++;total+=a->transactions[i].expense.amount;months[d.month-1]+=a->transactions[i].expense.amount;}}printSection("YEARLY EXPENSE REPORT");printf("Year: %d | Transactions: %zu | Total: Rs. %.2f\n",y,n,total);for(int m=0;m<12;m++)printf("  %02d  Rs. %.2f\n",m+1,months[m]);}
static void categoryReport(const AppState *a){double sums[CATEGORY_COUNT+MAX_CATEGORIES]={0};size_t counts[CATEGORY_COUNT+MAX_CATEGORIES]={0};double total=0;for(size_t i=0;i<a->transactionCount;i++){const Expense *e=&a->transactions[i].expense;size_t c=categoryIndexForTransaction(a,&a->transactions[i]);sums[c]+=e->amount;counts[c]++;total+=e->amount;}printSection("CATEGORY-WISE REPORT");for(size_t c=0;c<CATEGORY_COUNT+a->categoryCount;c++)printf("%-20s %3zu  Rs. %.2f  (%5.1f%%)\n",categoryDisplayNameAt(a,c),counts[c],sums[c],total?sums[c]/total*100:0);}
static void paymentReport(const AppState *a){double sums[PAYMENT_COUNT]={0};size_t counts[PAYMENT_COUNT]={0};for(size_t i=0;i<a->transactionCount;i++){const Transaction *t=&a->transactions[i];sums[t->paymentType]+=t->expense.amount;counts[t->paymentType]++;}printSection("PAYMENT METHOD REPORT");for(int p=0;p<PAYMENT_COUNT;p++)printf("%-8s %3zu transactions  Rs. %.2f\n",PAYMENT_NAMES[p],counts[p],sums[p]);}
static void extremeReport(const AppState *a,int high){if(!a->transactionCount){printInfo("No expenses are available.");return;}size_t best=0;for(size_t i=1;i<a->transactionCount;i++)if(high?a->transactions[i].expense.amount>a->transactions[best].expense.amount:a->transactions[i].expense.amount<a->transactions[best].expense.amount)best=i;printInfo(high?"Highest expense in the saved history:":"Lowest expense in the saved history:");printTransaction(&a->transactions[best]);}
void reportsMenu(const AppState *a){for(;;){printSection("EXPENSE REPORTS");puts("  1  Daily expense report");puts("  2  Monthly expense report");puts("  3  Yearly expense report");puts("  4  Category-wise report");puts("  5  Payment method report");puts("  6  Highest expense          7  Lowest expense");puts("  8  Monthly budget report");puts("  9  Complete financial summary");puts("  0  Return to main menu\n");int c;if(!readInt("Select a report: ",0,9,&c)){if(feof(stdin))return;continue;}if(!c)return;
        if(c==1)daily(a);else if(c==2||c==8){int m,y;if(reportInputs(&m,&y)){monthlyReport(a,m,y,stdout);if(c==8){const Budget *b=findBudget(a,m,y);if(!b)printInfo("No budget is configured for this period.");}}}
        else if(c==3)yearReport(a);else if(c==4)categoryReport(a);else if(c==5)paymentReport(a);else if(c==6)extremeReport(a,1);else if(c==7)extremeReport(a,0);else if(c==9){double total=0;for(size_t i=0;i<a->transactionCount;i++)total+=a->transactions[i].expense.amount;printSection("COMPLETE FINANCIAL SUMMARY");printf("Transactions: %zu | Lifetime spending: Rs. %.2f\n",a->transactionCount,total);categoryReport(a);paymentReport(a);}
        waitForEnter();}}
